                key=(len(c), max(sum(1 for p in c if I[p[0]][p[1]]==v) for v in {v for row in I for v in row})); 
                # pick by cell count then color count of majority
                cnts={}
                for p in c: cnts[I[p[0]][p[1]]]=cnts.get(I[p[0]][p[1]],0)+1
                maj,majc=sorted(cnts.items(),key=lambda kv:-kv[1])[0]
