    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for row in I for x in row); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; best=None
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=set(); col=I[i][j]; foreign=[]
                while q:
                    a,b=q.popleft(); cells.add((a,b))
                    for da,db in DIRS8:
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and I[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                frg=[(rr_,cc_) for rr_ in range(r0,r1+1) for cc_ in range(c0,c1+1) if I[rr_][cc_] not in (col,) and I[rr_][cc_]!=bg]
                key=(len(frg)==1,len(cells))
                if best is None or key>best[0]: best=(key,(r0,r1,c0,c1),col)
    _,bb,col=best
    r0,r1,c0,c1=bb
    frg=sorted(b for b in [(rr_,cc_) for rr_ in range(r0,r1+1) for cc_ in range(c0,c1+1) if I[rr_][cc_] not in (col,) and I[rr_][cc_]!=bg])
    out=[[col if (rr_,cc_)==frg[0] else I[rr_][cc_] for cc_ in range(c0,c1+1)] for rr_ in range(r0,r1+1)]
    return out
